UPDATE file_object f SET expires_at = #{now}, updated_at = #{now}
WHERE f.enterprise_id = #{enterprise} AND f.id IN
#{id}
AND f.purpose = 'attachment'
AND NOT EXISTS (SELECT 1 FROM message_attachment a WHERE a.enterprise_id = f.enterprise_id AND a.file_id = f.id)
AND NOT EXISTS (SELECT 1 FROM workspace_project_file p WHERE p.enterprise_id = f.enterprise_id AND p.file_id = f.id)
